// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : 
JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// 1. Puxar os clientes que estão a chegar do Merge (no caminho exato que a imagem mostra)
const clientes = $input.all()[0].json.body.clientes || [];

// 2. A tua tabela de investimentos que estava no ficheiro CSV
const investimentos = [
  { "perfil": "Conservador", "produto": "Poupança", "minimo": 100, "rentabilidade": "6.2%" },
  { "perfil": "Conservador", "produto": "CDB Liquidez Diária", "minimo": 1000, "rentabilidade": "12.5%" },
  { "perfil": "Conservador", "produto": "Tesouro Selic", "minimo": 500, "rentabilidade": "13.0%" },
  { "perfil": "Moderado", "produto": "CDB Prefixado", "minimo": 1000, "rentabilidade": "14.0%" },
  { "perfil": "Moderado", "produto": "Fundo Multimercado", "minimo": 5000, "rentabilidade": "16.0%" },
  { "perfil": "Moderado", "produto": "Tesouro IPCA+", "minimo": 1000, "rentabilidade": "IPCA+6.0%" },
  { "perfil": "Arrojado", "produto": "Ações ETF", "minimo": 500, "rentabilidade": "Variável" },
  { "perfil": "Arrojado", "produto": "Fundo de Ações", "minimo": 10000, "rentabilidade": "Variável" },
  { "perfil": "Arrojado", "produto": "Criptomoedas", "minimo": 100, "rentabilidade": "Variável" }
];

const resultados = [];

// Função para limpar o valor do saldo (ex: "R$ 12.500,00" vira 12500)
function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// 3. Analisar cada cliente e ver o que se encaixa
for (const cliente of clientes) {

  const nomeCliente = cliente.nome || "";
  const emailCliente = cliente.email || "";
  const perfilCliente = cliente.perfil || "";
  const saldoTexto = cliente.saldo || "";

  const saldoNum = parseBRL(saldoTexto);

  // Procurar o primeiro investimento que bata com o perfil E que o saldo dê
  const recomendacao = investimentos.find(inv => 
    inv.perfil.toLowerCase() === perfilCliente.toLowerCase() && saldoNum >= inv.minimo
  );

  // Se encontrou algo, gera as mensagens
  if (recomendacao) {
    const msgs = [
      `Olá ${nomeCliente}! Pelo seu perfil (${perfilCliente}), uma boa opção é **${recomendacao.produto}** (mínimo R$ ${recomendacao.minimo}). Com seu saldo atual (${saldoTexto}), você já consegue investir. Rentabilidade: ${recomendacao.rentabilidade}.`,
      `Oi ${nomeCliente}! Recomendação para perfil ${perfilCliente}: **${recomendacao.produto}** (mínimo R$ ${recomendacao.minimo}). Seu saldo (${saldoTexto}) já atende o mínimo. Rentabilidade: ${recomendacao.rentabilidade}.`,
      `${nomeCliente}, indo direto ao ponto: para o perfil ${perfilCliente}, **${recomendacao.produto}** (mínimo R$ ${recomendacao.minimo}). Você tem ${saldoTexto}, então dá pra aplicar. Rentabilidade: ${recomendacao.rentabilidade}.`
    ];

    resultados.push({
      nome: nomeCliente.trim(),
      email: emailCliente.trim(),
      perfil: perfilCliente,
      saldo_texto: saldoTexto,
      saldo_num: saldoNum,
      recomendacao: recomendacao,
      motivo: "saldo_ok",
      mensagem_base: msgs[0], 
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    });
  }
}

// 4. Devolver a resposta final
return resultados.map(resultado => {
  return {
    json: resultado
  };
});

const resultados = $json.resultados || [];

function parseBRL(valor) {
  if (!valor) return 0;
  const s = String(valor)
    .replace("R$", "")
    .replace(/\./g, "")
    .replace(",", ".")
    .replace(/[^\d.]/g, "")
    .trim();
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

// retorna UM ITEM por cliente
const out = resultados.map(c => {
  const saldoNum = c.saldo_num ?? parseBRL(c.saldo_texto ?? c.saldo);

  return {
    json: {
      email_to: String(c.email || "").trim(),
      nome: String(c.nome || "").trim(),
      perfil: c.perfil,
      saldo_texto: c.saldo_texto ?? c.saldo,
      saldo_num: saldoNum,
      recomendacao: c.recomendacao,
      motivo: c.motivo,
      mensagem_base: c.mensagem_escolhida || c.mensagem || "",
      copy_rules: {
        idioma: "pt-BR",
        tom: "amigável e profissional",
        tamanho: "curto (4-6 linhas)",
        evitar: ["promessas de ganho", "garantias", "linguagem agressiva"]
      }
    }
  };
});

return out;

