// 1. Puxar a lista de clientes intacta do nó inicial
const clientesOriginais = $items("Code in JavaScript1");

return $input.all().map((item, index) => {
  const cliente = clientesOriginais[index].json;

  // 2. O nosso "radar" à prova de bala: procura o texto gerado pela IA em qualquer lugar do labirinto
  function extrairTextoIA(obj) {
    if (typeof obj === 'string' && obj.includes('"subject"')) return obj;
    if (typeof obj === 'object' && obj !== null) {
      for (let key in obj) {
        let res = extrairTextoIA(obj[key]);
        if (res) return res;
      }
    }
    return null;
  }

  // 3. Usa o radar para apanhar a mensagem. Se falhar, devolve vazio "{}"
  let textoIA = extrairTextoIA(item.json) || "{}";

  let respostaIA = {};

  // 4. Limpar e traduzir o texto da IA para as variáveis finais
  try {
    const textoLimpo = textoIA.replace(/```json/gi, '').replace(/```/g, '').trim();
    respostaIA = JSON.parse(textoLimpo);
  } catch (erro) {
    respostaIA = {
      subject: "Erro ao ler assunto",
      text_body: "Erro ao ler texto",
      html_body: textoIA // Deixa o texto cru aqui caso haja erro para conseguirmos ver
    };
  }

  // 5. Montar a tabela final perfeita!
  return {
    json: {
      ok: true,
      to: cliente.email || cliente.Email || "",
      subject: respostaIA.subject || "",
      text_body: respostaIA.text_body || "",
      html_body: respostaIA.html_body || "",
      meta: {
        nome: cliente.nome || cliente.Nome,
        perfil: cliente.perfil || cliente.Perfil,
        produto: cliente.recomendacao?.produto,
        minimo: cliente.recomendacao?.minimo,
        rentabilidade: cliente.recomendacao?.rentabilidade,
        motivo: cliente.motivo
      }
    }
  };
});
